# 70_lords_scandal_breaktest.R
#
# Has the Lords "bad behaviour" case list increased over 1979-2025? PJ,
# 12 Sep 2026: "not to forget to do a test as to whether lords scandals have
# statistically increased over the period." Same Poisson change-point /
# likelihood-ratio + permutation-significance method already standing in
# this project for rare-events count series (see 48_scandal_rare_event_test.R
# for the Commons ministerial-scandal equivalent) — sup-LR over every
# candidate split year, significance by permutation (10,000 draws) rather
# than trusting chi-sq(1) asymptotics with only 12 events.
#
# No exposure/offset term here (unlike 48's per-100-ministers rate) — there
# is no natural varying population to normalise the Lords case list against,
# so this is a plain Poisson rate-change test on the raw annual counts.
#
# ⚠⚠ CAVEAT THAT MATTERS MORE HERE THAN FOR ANY OTHER BREAK TEST IN THIS
# PROJECT: this case list is PJ's own web-search-compiled illustrative list,
# NOT a systematic census (see sources_raw/local_govt_scandals_web_compiled/
# SOURCE_NOTE.md for the parallel caveat on the local-government list — the
# same logic applies here). Web search systematically UNDERCOUNTS
# pre-internet-era events (1980s-90s press coverage is poorly indexed) while
# over-finding recent, well-documented cases. That bias runs in exactly the
# direction that would MANUFACTURE an apparent "increase" even if none
# occurred. Unlike 48's test (a genuine systematic series), a significant
# result here would be at least as likely to reflect search-era visibility
# as a real behavioural change - report any p-value with that caveat
# attached, not as a clean finding.
#
# DATA: hand-entered below from the case list compiled 12 Sep 2026 (not yet
# a standalone CSV — see project memory for the full case-by-case sourcing).
# OUTPUT: console only - diagnostic.

set.seed(42)
NPERM <- 10000
YEARS <- 1979:2025

events <- c(`1980` = 1, `2001` = 1, `2005` = 1, `2009` = 2, `2010` = 2,
            `2011` = 2, `2015` = 1, `2018` = 1, `2020` = 1)
y <- setNames(rep(0, length(YEARS)), YEARS)
y[names(events)] <- events
y <- as.numeric(y)
cat(sprintf("N years = %d, total events = %d\n", length(y), sum(y)))

poisson_LR <- function(y, k, min_seg = 3) {
  n <- length(y)
  if (k < min_seg || k > n - min_seg) return(NA_real_)
  period <- factor(rep(c("pre", "post"), c(k, n - k)))
  m_pool  <- glm(y ~ 1, family = poisson)
  m_split <- tryCatch(glm(y ~ period, family = poisson),
                       warning = function(w) NULL, error = function(e) NULL)
  if (is.null(m_split)) return(NA_real_)
  2 * (as.numeric(logLik(m_split)) - as.numeric(logLik(m_pool)))
}

.ks_interior <- function(n, trim = 0.15, min_seg = 3) {
  lo <- max(min_seg, floor(trim * n)); hi <- min(n - min_seg, n - floor(trim * n)); lo:hi
}
supLR <- function(y, year, trim = 0.15, min_seg = 3) {
  n <- length(y); ks <- .ks_interior(n, trim, min_seg)
  lr <- vapply(ks, function(k) poisson_LR(y, k, min_seg), numeric(1))
  list(peak_year = year[ks[which.max(lr)]], peak_LR = max(lr, na.rm = TRUE),
       curve = data.frame(year = year[ks], LR = lr))
}
perm_pvalue <- function(y, year, observed_LR, trim = 0.15, min_seg = 3, nperm = NPERM) {
  perm_max <- replicate(nperm, supLR(sample(y), year, trim, min_seg)$peak_LR)
  mean(perm_max >= observed_LR, na.rm = TRUE)
}

res  <- supLR(y, YEARS)
pval <- perm_pvalue(y, YEARS, res$peak_LR)

cat(sprintf("\n=== Poisson change-point test, Lords case list (rare-events method) ===\n"))
cat(sprintf("Peak break year: %d, LR = %.2f, permutation p = %.4f (%d draws)\n",
            res$peak_year, res$peak_LR, pval, NPERM))
cat("Top 5 candidate years by LR (break year not well pinned down at this N):\n")
print(res$curve[order(-res$curve$LR), ][1:5, ])

k <- which(YEARS == res$peak_year)
rate_pre  <- sum(y[1:k]) / k
rate_post <- sum(y[(k + 1):length(y)]) / (length(y) - k)
cat(sprintf("\nRate before %d: %.3f events/year (n=%d events, %d years)\n",
            res$peak_year, rate_pre, sum(y[1:k]), k))
cat(sprintf("Rate from %d:  %.3f events/year (n=%d events, %d years)\n",
            res$peak_year, rate_post, sum(y[(k + 1):length(y)]), length(y) - k))
cat("\nSee header caveat: web-search-compiled list, not a census - a search-era\n")
cat("visibility artefact could produce this exact pattern even with no real change.\n")
